1	#include "ncnn_llm_ocr.h"
2	#include "utils/vision_rope.h"
3	
4	ncnn_llm_ocr::ncnn_llm_ocr(const std::string& model_path, bool use_vulkan, int num_threads)
5	    : ncnn_llm_base(use_vulkan, num_threads > 0 ? num_threads : 4) {
6	    try {
7	        json config;
8	        {
9	            std::ifstream ifs(model_path + "/model.json");
10	            ifs >> config;
11	        }
12	        if (config.contains("model_type")) {
13	            model_type_ = config["model_type"].get<std::string>();
14	        }
15	
16	        vision_net_ = std::make_shared<ncnn::Net>();
17	        text_embed_net_ = std::make_shared<ncnn::Net>();
18	        text_decoder_net_ = std::make_shared<ncnn::Net>();
19	        lm_head_net_ = std::make_shared<ncnn::Net>();
20	
21	        if (num_threads > 0) {
22	            vision_net_->opt.num_threads = num_threads;
23	            text_embed_net_->opt.num_threads = num_threads;
24	            text_decoder_net_->opt.num_threads = num_threads;
25	            lm_head_net_->opt.num_threads = num_threads;
26	        }
27	
28	        if (use_vulkan) {
29	            printf("[ncnn_llm_ocr] Vulkan enabled\n");
30	            vision_net_->opt.use_vulkan_compute = true;
31	            text_decoder_net_->opt.use_vulkan_compute = true;
32	            text_decoder_net_->opt.use_bf16_storage = true;
33	            text_decoder_net_->opt.use_fp16_arithmetic = false;
34	            text_decoder_net_->opt.use_fp16_storage = false;
35	        } else {
36	            printf("[ncnn_llm_ocr] Vulkan disabled, using CPU only\n");
37	        }
38	
39	        std::string vision_param = model_path + "/" + config["params"]["vision_param"].get<std::string>();
40	        std::string vision_bin = model_path + "/" + config["params"]["vision_bin"].get<std::string>();
41	        std::string text_embed_param = model_path + "/" + config["params"]["text_embed_param"].get<std::string>();
42	        std::string text_embed_bin = model_path + "/" + config["params"]["text_embed_bin"].get<std::string>();
43	        std::string text_decoder_param = model_path + "/" + config["params"]["text_decoder_param"].get<std::string>();
44	        std::string text_decoder_bin = model_path + "/" + config["params"]["text_decoder_bin"].get<std::string>();
45	        std::string lm_head_param = model_path + "/" + config["params"]["lm_head_param"].get<std::string>();
46	        std::string lm_head_bin = model_path + "/" + config["params"]["lm_head_bin"].get<std::string>();
47	
48	        printf("Loading OCR model (%s) from %s\n", model_type_.c_str(), model_path.c_str());
49	        printf("  vision param: %s\n", vision_param.c_str());
50	        printf("  vision bin: %s\n", vision_bin.c_str());
51	        printf("  text_embed param: %s\n", text_embed_param.c_str());
52	        printf("  text_embed bin: %s\n", text_embed_bin.c_str());
53	        printf("  text_decoder param: %s\n", text_decoder_param.c_str());
54	        printf("  text_decoder bin: %s\n", text_decoder_bin.c_str());
55	        printf("  lm_head param: %s\n", lm_head_param.c_str());
56	        printf("  lm_head bin: %s\n", lm_head_bin.c_str());
57	
58	        vision_net_->load_param(vision_param.c_str());
59	        vision_net_->load_model(vision_bin.c_str());
60	        text_embed_net_->load_param(text_embed_param.c_str());
61	        text_embed_net_->load_model(text_embed_bin.c_str());
62	        text_decoder_net_->load_param(text_decoder_param.c_str());
63	        text_decoder_net_->load_model(text_decoder_bin.c_str());
64	        lm_head_net_->load_param(lm_head_param.c_str());
65	        lm_head_net_->load_model(lm_head_bin.c_str());
66	
67	        std::string type = "bpe";
68	        if (config["tokenizer"].contains("type")) {
69	            type = config["tokenizer"]["type"].get<std::string>();
70	        }
71	        std::string vocab_file = model_path + "/" + config["tokenizer"]["vocab_file"].get<std::string>();
72	        std::string merges_file = model_path + "/" + config["tokenizer"]["merges_file"].get<std::string>();
73	
74	        bpe_ = std::make_shared<BpeTokenizer>(BpeTokenizer::LoadFromFiles(
75	            vocab_file, merges_file, SpecialTokensConfig{}, false, true, type == "bbpe"
76	        ));
77	
78	        std::vector<std::string> additional_special_tokens = config["tokenizer"]["additional_special_tokens"].get<std::vector<std::string>>();
79	        for (const auto& token : additional_special_tokens) {
80	            bpe_->AddAdditionalSpecialToken(token);
81	        }
82	        // Build set of additional special token IDs for fast lookup
83	        for (int id : bpe_->additional_special_token_ids()) {
84	            additional_special_id_set_.insert(id);
85	        }
86	
87	        auto eos_token = config["tokenizer"]["eos"].get<std::string>();
88	        eos_ = (eos_token != "") ? bpe_->token_to_id().at(eos_token) : -1;
89	        auto it_eop = bpe_->token_to_id().find("<eop>");
90	        eop_ = (it_eop != bpe_->token_to_id().end()) ? it_eop->second : -1;
91	        if (config["tokenizer"].contains("eos_ids")) {
92	            for (auto& v : config["tokenizer"]["eos_ids"]) {
93	                eos_ids_.insert(v.get<int>());
94	            }
95	        }
96	
97	        if (config["setting"].contains("attn_cnt")) {
98	            attn_cnt_ = config["setting"]["attn_cnt"].get<int>();
99	        }
100	        if (config["setting"].contains("hidden_size")) {
101	            hidden_size_ = config["setting"]["hidden_size"].get<int>();
102	        }
103	        if (config["setting"].contains("head_dim")) {
104	            head_dim_ = config["setting"]["head_dim"].get<int>();
105	        }
106	        if (config["setting"].contains("image_token_id")) {
107	            image_token_id_ = config["setting"]["image_token_id"].get<int>();
108	        }
109	
110	        if (model_type_ == "hunyuan_ocr") {
111	            // ---- HunyuanOCR: 4-axis xdrope, vision without RoPE, no KV cache ----
112	            use_kv_cache_ = config["setting"].value("kv_cache", false);
113	            auto rope_cfg = config["setting"]["rope"];
114	            if (!rope_cfg.contains("type") || rope_cfg["type"].get<std::string>() != "xdrope") {
115	                throw std::runtime_error("hunyuan_ocr requires setting.rope.type == xdrope");
116	            }
117	            rope_theta_ = rope_cfg.value("rope_theta", 10000.0f);
118	            head_dim_ = rope_cfg.value("rope_head_dim", head_dim_);
119	            rope_alpha_ = rope_cfg.value("alpha", 1000.0f);
120	            for (auto& v : rope_cfg["xdrope_section"]) {
121	                xdrope_section_.push_back(v.get<int>());
122	            }
123	            int sect_sum = 0;
124	            for (int s : xdrope_section_) sect_sum += s;
125	            if (xdrope_section_.empty() || sect_sum != head_dim_ / 2) {
126	                throw std::runtime_error("setting.rope.xdrope_section must sum to rope_head_dim/2");
127	            }
128	
129	            bos_id_ = config["setting"].value("bos_token_id", 120000);
130	            system_end_id_ = config["setting"].value("system_end_token_id", 120021);
131	            user_end_id_ = config["setting"].value("user_end_token_id", 120006);
132	            image_start_id_ = config["setting"].value("image_start_token_id", 120118);
133	            image_end_id_ = config["setting"].value("image_end_token_id", 120119);
134	            special_id_begin_ = config["setting"].value("special_token_id_begin", 120000);
135	
136	            auto vision_cfg = config["setting"]["vision"];
137	            patch_size_ = vision_cfg.value("patch_size", 16);
138	            spatial_merge_size_ = vision_cfg.value("spatial_merge_size", 2);
139	            vision_hidden_size_ = vision_cfg.value("vision_hidden_size", 1152);
140	            if (vision_cfg.contains("min_pixels")) min_pixels_ = vision_cfg["min_pixels"].get<long long>();
141	            if (vision_cfg.contains("max_pixels")) max_pixels_ = vision_cfg["max_pixels"].get<long long>();
142	            if (vision_cfg.contains("image_mean")) {
143	                auto mean = vision_cfg["image_mean"].get<std::vector<float>>();
144	                image_mean_[0] = mean[0]; image_mean_[1] = mean[1]; image_mean_[2] = mean[2];
145	            }
146	            if (vision_cfg.contains("image_std")) {
147	                auto std_vals = vision_cfg["image_std"].get<std::vector<float>>();
148	                image_std_[0] = std_vals[0]; image_std_[1] = std_vals[1]; image_std_[2] = std_vals[2];
149	            }
150	
151	            vocab_size_ = config["setting"].value("vocab_size", (int)bpe_->vocab_size());
152	            printf("  [hunyuan_ocr] attn_cnt: %d, hidden_size: %d, head_dim: %d, vocab_size: %d\n",
153	                   attn_cnt_, hidden_size_, head_dim_, vocab_size_);
154	            printf("  [hunyuan_ocr] patch_size: %d, merge_size: %d, min/max_pixels: %lld/%lld\n",
155	                   patch_size_, spatial_merge_size_, min_pixels_, max_pixels_);
156	            printf("  [hunyuan_ocr] rope_theta: %.1f, alpha: %.1f, xdrope_section size: %d, kv_cache: %d\n",
157	                   rope_theta_, rope_alpha_, (int)xdrope_section_.size(), (int)use_kv_cache_);
158	            printf("  [hunyuan_ocr] image_token_id: %d, image_start: %d, image_end: %d, bos: %d, user_end: %d\n",
159	                   image_token_id_, image_start_id_, image_end_id_, bos_id_, user_end_id_);
160	        } else {
161	            if (config["setting"].contains("rope")) {
162	                auto text_rope_cfg = config["setting"]["rope"];
163	                if (!text_rope_cfg.contains("type") || text_rope_cfg["type"].get<std::string>() != "mRoPE") {
164	                    throw std::runtime_error("unsupported setting.rope.type in model.json");
165	                }
166	                if (text_rope_cfg.contains("rope_theta")) {
167	                    rope_theta_ = text_rope_cfg["rope_theta"].get<float>();
168	                }
169	                if (text_rope_cfg.contains("rope_head_dim")) {
170	                    head_dim_ = text_rope_cfg["rope_head_dim"].get<int>();
171	                }
172	                if (!text_rope_cfg.contains("mrope_section")) {
173	                    throw std::runtime_error("missing setting.rope.mrope_section in model.json");
174	                }
175	                for (auto& v : text_rope_cfg["mrope_section"]) {
176	                    mrope_section_.push_back(v.get<int>());
177	                }
178	            } else if (config["setting"].contains("rope_theta") || config["setting"].contains("mrope_section")) {
179	                throw std::runtime_error("legacy setting.rope_theta/mrope_section is not supported; use setting.rope");
180	            } else {
181	                throw std::runtime_error("missing setting.rope in model.json");
182	            }
183	            if (mrope_section_.size() != 3) {
184	                throw std::runtime_error("setting.rope.mrope_section must have 3 entries");
185	            }
186	
187	            if (config["setting"].contains("vision")) {
188	                auto vision_cfg = config["setting"]["vision"];
189	                if (vision_cfg.contains("patch_size")) {
190	                    patch_size_ = vision_cfg["patch_size"].get<int>();
191	                }
192	                if (vision_cfg.contains("spatial_merge_size")) {
193	                    spatial_merge_size_ = vision_cfg["spatial_merge_size"].get<int>();
194	                }
195	                if (vision_cfg.contains("vision_hidden_size")) {
196	                    vision_hidden_size_ = vision_cfg["vision_hidden_size"].get<int>();
197	                }
198	                if (vision_cfg.contains("vision_head_dim")) {
199	                    vision_head_dim_ = vision_cfg["vision_head_dim"].get<int>();
200	                }
201	                if (vision_cfg.contains("vision_num_heads")) {
202	                    vision_num_heads_ = vision_cfg["vision_num_heads"].get<int>();
203	                }
204	                if (!vision_cfg.contains("rope")) {
205	                    throw std::runtime_error("missing setting.vision.rope in model.json");
206	                }
207	                auto vision_rope_cfg = vision_cfg["rope"];
208	                if (!vision_rope_cfg.contains("type") || vision_rope_cfg["type"].get<std::string>() != "mRoPE") {
209	                    throw std::runtime_error("unsupported setting.vision.rope.type in model.json");
210	                }
211	                if (vision_rope_cfg.contains("rope_theta")) {
212	                    vision_rope_theta_ = vision_rope_cfg["rope_theta"].get<float>();
213	                }
214	                if (vision_rope_cfg.contains("rope_head_dim")) {
215	                    vision_rope_dim_ = vision_rope_cfg["rope_head_dim"].get<int>();
216	                }
217	                if (!vision_rope_cfg.contains("mrope_section")) {
218	                    throw std::runtime_error("missing setting.vision.rope.mrope_section in model.json");
219	                }
220	                for (auto& v : vision_rope_cfg["mrope_section"]) {
221	                    vision_mrope_section_.push_back(v.get<int>());
222	                }
223	                if (vision_rope_theta_ <= 0.0f || vision_rope_dim_ <= 0 || (vision_rope_dim_ % 2) != 0) {
224	                    throw std::runtime_error("invalid setting.vision.rope rope_theta/rope_head_dim in model.json");
225	                }
226	                if (vision_mrope_section_.size() != 2 ||
227	                    vision_mrope_section_[0] + vision_mrope_section_[1] != vision_rope_dim_) {
228	                    throw std::runtime_error("setting.vision.rope.mrope_section must be [h_dim,w_dim] and sum to rope_head_dim");
229	                }
230	                if (vision_cfg.contains("max_num_patches")) {
231	                    max_num_patches_ = vision_cfg["max_num_patches"].get<int>();
232	                }
233	                if (vision_cfg.contains("min_pixels")) {
234	                    min_pixels_ = vision_cfg["min_pixels"].get<long long>();
235	                }
236	                if (vision_cfg.contains("max_pixels")) {
237	                    max_pixels_ = vision_cfg["max_pixels"].get<long long>();
238	                }
239	                if (vision_cfg.contains("image_mean")) {
240	                    auto mean = vision_cfg["image_mean"].get<std::vector<float>>();
241	                    image_mean_[0] = mean[0]; image_mean_[1] = mean[1]; image_mean_[2] = mean[2];
242	                }
243	                if (vision_cfg.contains("image_std")) {
244	                    auto std_vals = vision_cfg["image_std"].get<std::vector<float>>();
245	                    image_std_[0] = std_vals[0]; image_std_[1] = std_vals[1]; image_std_[2] = std_vals[2];
246	                }
247	            }
248	
249	            vocab_size_ = (int)bpe_->vocab_size();
250	            printf("  attn_cnt: %d, hidden_size: %d, head_dim: %d, vocab_size: %d\n", attn_cnt_, hidden_size_, head_dim_, vocab_size_);
251	            printf("  patch_size: %d, spatial_merge_size: %d, max_num_patches: %d\n", patch_size_, spatial_merge_size_, max_num_patches_);
252	            printf("  text mrope_section: [%d %d %d]\n", mrope_section_[0], mrope_section_[1], mrope_section_[2]);
253	            printf("  vision rope: type=mRoPE, rope_theta=%.1f, rope_head_dim=%d, mrope_section=[%d %d]\n",
254	                   vision_rope_theta_, vision_rope_dim_, vision_mrope_section_[0], vision_mrope_section_[1]);
255	            printf("  min_pixels: %lld, max_pixels: %lld, image_mean/std: [%.6f %.6f %.6f] / [%.6f %.6f %.6f]\n",
256	                   min_pixels_, max_pixels_,
257	                   image_mean_[0], image_mean_[1], image_mean_[2],
258	                   image_std_[0], image_std_[1], image_std_[2]);
259	            printf("  image_token_id: %d, eos: %d, eop: %d\n", image_token_id_, eos_, eop_);
260	        }
261	
262	    } catch (std::exception &e) {
263	        ok_ = false;
264	        throw std::runtime_error(std::string("ncnn_llm_ocr load model failed: ") + e.what());
265	    }
266	}
267	
268	void ncnn_llm_ocr::get_image_size_for_patches(int img_h, int img_w, int& target_h, int& target_w) const {
269	    int effective_patch_size = patch_size_ * spatial_merge_size_;
270	
271	    auto round_by_factor = [&](double size) -> int {
272	        int result = (int)(std::round(size / (double)effective_patch_size) * effective_patch_size);
273	        return std::max(effective_patch_size, result);
274	    };
275	
276	    double h = (double)img_h;
277	    double w = (double)img_w;
278	    double area = h * w;
279	
280	    double scale = 1.0;
281	    if (area > (double)max_pixels_) {
282	        scale = std::sqrt((double)max_pixels_ / area);
283	    } else if (area < (double)min_pixels_) {
284	        scale = std::sqrt((double)min_pixels_ / area);
285	    }
286	
287	    target_h = round_by_factor(h * scale);
288	    target_w = round_by_factor(w * scale);
289	}
290	
291	ncnn::Mat ncnn_llm_ocr::bgr_to_image_strip(const ncnn::Mat& bgr, int& num_patches_h, int& num_patches_w) const {
292	    int img_h = bgr.h;
293	    int img_w = bgr.w;
294	
295	    int target_h, target_w;
296	    get_image_size_for_patches(img_h, img_w, target_h, target_w);
297	
298	    ncnn::Mat bgr_resized = ncnn_mat_resize(bgr, target_w, target_h);
299	
300	    num_patches_h = target_h / patch_size_;
301	    num_patches_w = target_w / patch_size_;
302	    int num_patches = num_patches_h * num_patches_w;
303	
304	    const unsigned char* bgr_data = (const unsigned char*)bgr_resized.data;
305	
306	    // Match the TorchScript wrapper:
307	    // pv.view(1, N, 3, 2, 14, 14)[:, :, :, 0].permute(0, 2, 3, 1, 4)
308	    //   .reshape(1, 3, 14, 14 * N)
309	    // The N dimension is already grouped by 2x2 spatial merge blocks.
310	    ncnn::Mat image_strip(patch_size_ * num_patches, patch_size_, 3);
311	    image_strip.fill(0.0f);
312	
313	    int grid_h = num_patches_h / spatial_merge_size_;
314	    int grid_w = num_patches_w / spatial_merge_size_;
315	    int patch_idx = 0;
316	
317	    for (int gh = 0; gh < grid_h; gh++) {
318	        for (int gw = 0; gw < grid_w; gw++) {
319	            for (int mh = 0; mh < spatial_merge_size_; mh++) {
320	                for (int mw = 0; mw < spatial_merge_size_; mw++) {
321	                    int patch_h = gh * spatial_merge_size_ + mh;
322	                    int patch_w = gw * spatial_merge_size_ + mw;
323	                    int start_y = patch_h * patch_size_;
324	                    int start_x = patch_w * patch_size_;
325	                    int strip_base_x = patch_idx * patch_size_;
326	
327	                    for (int y = 0; y < patch_size_; y++) {
328	                        const unsigned char* img_row_ptr = bgr_data + (start_y + y) * target_w * 3;
329	                        float* dst_r = image_strip.channel(0).row(y) + strip_base_x;
330	                        float* dst_g = image_strip.channel(1).row(y) + strip_base_x;
331	                        float* dst_b = image_strip.channel(2).row(y) + strip_base_x;
332	
333	                        for (int x = 0; x < patch_size_; x++) {
334	                            const unsigned char* pixel = img_row_ptr + (start_x + x) * 3;
335	                            dst_r[x] = (pixel[2] / 255.0f - image_mean_[0]) / image_std_[0];
336	                            dst_g[x] = (pixel[1] / 255.0f - image_mean_[1]) / image_std_[1];
337	                            dst_b[x] = (pixel[0] / 255.0f - image_mean_[2]) / image_std_[2];
338	                        }
339	                    }
340	
341	                    patch_idx++;
342	                }
343	            }
344	        }
345	    }
346	
347	    return image_strip;
348	}
