350	ncnn::Mat ncnn_llm_ocr::run_vision(const ncnn::Mat& image_strip, const ncnn::Mat& cos_cache, const ncnn::Mat& sin_cache) const {
351	    ncnn::Mat vision_features;
352	    ncnn::Extractor ex = vision_net_->create_extractor();
353	    ex.input("in0", image_strip);
354	    ex.input("in1", cos_cache);
355	    ex.input("in2", sin_cache);
356	    ex.extract("out0", vision_features);
357	    return vision_features;
358	}
