360	void ncnn_llm_ocr::generate_text_rope_cache(int seq_len, int position_id, ncnn::Mat& cos_cache, ncnn::Mat& sin_cache) const {
361	    // GLM-OCR text decoder uses interleaved RoPE (head_dim=128, but cos/sin are [seq_len, 64])
362	    generate_rope_embed_cache(seq_len, head_dim_, position_id, cos_cache, sin_cache, rope_theta_);
363	}
