365	std::shared_ptr<ncnn_llm_gpt_ctx> ncnn_llm_ocr::prefill(const std::string& prompt_text, const ncnn::Mat& bgr_image) {
366	    if (model_type_ == "hunyuan_ocr") {
367	        return prefill_hunyuan(prompt_text, bgr_image);
368	    }
369	    // Run vision model
370	    int num_patches_h = 0, num_patches_w = 0;
371	    ncnn::Mat image_strip = bgr_to_image_strip(bgr_image, num_patches_h, num_patches_w);
372	    int num_patches = num_patches_h * num_patches_w;
373	
374	    ncnn::Mat vision_cos, vision_sin;
375	    generate_vision_rope_cache_2d(num_patches_h, num_patches_w, spatial_merge_size_,
376	                                  vision_rope_theta_, vision_mrope_section_,
377	                                  false, vision_cos, vision_sin);
378	
379	    ncnn::Mat vision_features = run_vision(image_strip, vision_cos, vision_sin);
380	    int num_vision_tokens = vision_features.h;
381	
382	    // Build prompt with image tokens, matching
383	    // tokenizer.apply_chat_template(..., add_generation_prompt=true, enable_thinking=false).
384	    std::string full_prompt = "[gMASK]<sop><|user|>\n<|begin_of_image|>";
385	    for (int i = 0; i < num_vision_tokens; i++) {
386	        full_prompt += "<|image|>";
387	    }
388	    full_prompt += "<|end_of_image|>" + prompt_text;
389	    if (prompt_text.size() < 8 || prompt_text.rfind("/nothink") != prompt_text.size() - 8) {
390	        full_prompt += "/nothink";
391	    }
392	    full_prompt += "<|assistant|>\n<think></think>\n";
393	
394	    // Tokenize prompt
395	    std::vector<int> token_ids = bpe_->encode(full_prompt, false, false);
396	
397	    // Get text embeddings
398	    ncnn::Mat token_embed = llm_run_text_embed(*text_embed_net_, token_ids);
399	
400	    // Find image token positions and inject vision features
401	    std::vector<int> image_token_positions;
402	    for (int i = 0; i < (int)token_ids.size(); i++) {
403	        if (token_ids[i] == image_token_id_) {
404	            image_token_positions.push_back(i);
405	        }
406	    }
407	    // Replace image token embeddings with vision features
408	    if ((int)image_token_positions.size() == num_vision_tokens) {
409	        for (int i = 0; i < num_vision_tokens; i++) {
410	            int pos = image_token_positions[i];
411	            float* embed_ptr = token_embed.row(pos);
412	            const float* feat_ptr = vision_features.row(i);
413	            memcpy(embed_ptr, feat_ptr, hidden_size_ * sizeof(float));
414	        }
415	    } else {
416	        printf("[ncnn_llm_ocr] WARNING: image token count mismatch! vision_tokens=%d, image_tokens_in_prompt=%d\n",
417	               num_vision_tokens, (int)image_token_positions.size());
418	    }
419	
420	    // Generate causal mask
421	    int seq_len = (int)token_ids.size();
422	    ncnn::Mat mask(seq_len, seq_len);
423	    mask.fill(0.0f);
424	    for (int i = 0; i < seq_len; i++) {
425	        float* row = mask.row(i);
426	        for (int j = i + 1; j < seq_len; j++) {
427	            row[j] = -1e38f;
428	        }
429	    }
430	
431	    // Generate MRoPE cache for text decoder (image tokens have 2D positions)
432	    // GLM-OCR text decoder uses interleaved RoPE with cos/sin shape [seq_len, 64]
433	    ncnn::Mat cos_cache, sin_cache;
434	    int next_position_id = seq_len;
435	    if (!mrope_section_.empty() && !image_token_positions.empty()) {
436	        generate_rope_embed_cache_vision_mrope(seq_len, head_dim_, 0,
437	                                               image_token_positions[0], num_vision_tokens,
438	                                               num_patches_w, spatial_merge_size_,
439	                                               mrope_section_, cos_cache, sin_cache, rope_theta_);
440	        next_position_id = seq_len - num_vision_tokens + (num_patches_w / spatial_merge_size_);
441	    } else {
442	        generate_text_rope_cache(seq_len, 0, cos_cache, sin_cache);
443	    }
444	
445	    // Run decoder (prefill pass, no existing KV cache)
446	    KVCache kv_cache;
447	    ncnn::Mat decode_out = llm_run_decoder_with_kv(*text_decoder_net_, token_embed, mask, cos_cache, sin_cache,
448	                                                   kv_cache, attn_cnt_, true);
449	
450	    // Run lm_head on the last token
451	    ncnn::Mat last_hidden = decode_out.row_range(seq_len - 1, 1);
452	    ncnn::Mat logits = llm_run_lm_head(*lm_head_net_, last_hidden);
453	
454	    // Get next token via argmax
455	    int next_token_id = argmax1d(logits);
456	
457	    // Create and return context
458	    auto ctx = std::make_shared<ncnn_llm_gpt_base_ctx>();
459	    ctx->kv_cache = std::move(kv_cache);
460	    ctx->cur_token = next_token_id;
461	    ctx->position_id = next_position_id;
462	    return ctx;
463	}
464	
465	std::shared_ptr<ncnn_llm_gpt_ctx> ncnn_llm_ocr::generate(
466	    const std::shared_ptr<ncnn_llm_gpt_ctx>& ctx_in,
467	    const GenerateConfig& cfg,
468	    std::function<void(const std::string&)> callback) {
469	
470	    if (model_type_ == "hunyuan_ocr") {
471	        return generate_hunyuan(ctx_in, cfg, callback);
472	    }
473	
474	    auto ctx = ctx_in->clone();
475	    std::unordered_set<int> history;
476	    history.insert(ctx->cur_token);
477	    std::string emitted_text;
478	
479	    for (int step = 0; step < cfg.max_new_tokens; ++step) {
480	        if (ctx->cur_token == eos_ || ctx->cur_token == eop_) break;
481	
482	        // Skip outputting the first token if it's a special token (e.g. </think|>)
483	        // The model may output </think|> as the first token in non-thinking mode
484	        bool is_special = (ctx->cur_token == eos_) ||
485	                          (ctx->cur_token == eop_) ||
486	                          (additional_special_id_set_.find(ctx->cur_token) != additional_special_id_set_.end());
487	        if (!is_special) {
488	            std::string token_text = bpe_->decode({ctx->cur_token}, false);
489	            if (!emitted_text.empty() && token_text.find("```") != std::string::npos) {
490	                break;
491	            }
492	
493	            std::string candidate_text = emitted_text + token_text;
494	            int trailing_newlines = 0;
495	            for (auto it = candidate_text.rbegin(); it != candidate_text.rend(); ++it) {
496	                if (*it == '\n') {
497	                    trailing_newlines++;
498	                } else if (*it == '\r') {
499	                    continue;
500	                } else {
501	                    break;
502	                }
503	            }
504	            if (!emitted_text.empty() && trailing_newlines > 2) {
505	                break;
506	            }
507	            emitted_text += token_text;
508	            callback(token_text);
509	        }
510	
511	        ncnn::Mat cur_embed = llm_run_text_embed(*text_embed_net_, ctx->cur_token);
512	
513	        // Generate RoPE cache for single token
514	        ncnn::Mat cos_cache, sin_cache;
515	        generate_text_rope_cache(1, ctx->position_id, cos_cache, sin_cache);
516	        ctx->position_id++;
517	
518	        // Create mask: [1, kv_len+1] all zeros (new token can attend to all previous)
519	        ncnn::Mat mask(1, ctx->kv_cache[0].first.h + 1);
520	        mask.fill(0.0f);
521	
522	        ncnn::Mat decode_out = llm_run_decoder_with_kv(*text_decoder_net_, cur_embed, mask, cos_cache, sin_cache,
523	                                                       ctx->kv_cache, attn_cnt_, false);
524	
525	        ncnn::Mat logits = llm_run_lm_head(*lm_head_net_, decode_out);
526	
527	        LlmTokenSampleConfig sample_cfg;
528	        sample_cfg.vocab_size = vocab_size_;
529	        sample_cfg.temperature = cfg.temperature;
530	        sample_cfg.top_p = cfg.top_p;
531	        sample_cfg.top_k = cfg.top_k;
532	        sample_cfg.repetition_penalty = cfg.repetition_penalty;
533	        sample_cfg.do_sample = cfg.do_sample;
534	        int next_id = llm_select_next_token(logits, history, sample_cfg);
535	
536	        ctx->cur_token = next_id;
537	        history.insert(next_id);
538	    }
539	
540	    return ctx;
541	}
