543	// ============================================================================ HunyuanOCR path
544	
545	void ncnn_llm_ocr::smart_resize_hunyuan(int img_h, int img_w, int& target_h, int& target_w) const {
546	    const long long factor = (long long)patch_size_ * spatial_merge_size_; // 32
547	
548	    auto round_half_even = [](double x) -> long long {
549	        double fl = std::floor(x);
550	        double diff = x - fl;
551	        if (diff < 0.5) return (long long)fl;
552	        if (diff > 0.5) return (long long)fl + 1;
553	        long long lo = (long long)fl;                 // exactly .5 -> round to even (Python round)
554	        return (lo % 2 == 0) ? lo : lo + 1;
555	    };
556	
557	    long long h_bar = std::max(factor, round_half_even((double)img_h / (double)factor) * factor);
558	    long long w_bar = std::max(factor, round_half_even((double)img_w / (double)factor) * factor);
559	    const double area = (double)img_h * (double)img_w;
560	
561	    if (h_bar * w_bar > (long long)max_pixels_) {
562	        double beta = std::sqrt(area / (double)max_pixels_);
563	        h_bar = std::max(factor, (long long)std::floor(img_h / beta / factor) * factor);
564	        w_bar = std::max(factor, (long long)std::floor(img_w / beta / factor) * factor);
565	    } else if (h_bar * w_bar < (long long)min_pixels_) {
566	        double beta = std::sqrt((double)min_pixels_ / area);
567	        h_bar = (long long)std::ceil(img_h * beta / factor) * factor;
568	        w_bar = (long long)std::ceil(img_w * beta / factor) * factor;
569	    }
570	
571	    target_h = (int)h_bar;
572	    target_w = (int)w_bar;
573	}
574	
575	ncnn::Mat ncnn_llm_ocr::bgr_to_chw_image_hunyuan(const ncnn::Mat& bgr, int& target_h, int& target_w) const {
576	    smart_resize_hunyuan(bgr.h, bgr.w, target_h, target_w);
577	
578	    // PIL resizes the uint8 image with BICUBIC, then ToTensor(/255)+Normalize.
579	    ncnn::Mat resized = ncnn_mat_resize_bicubic(bgr, target_w, target_h);  // interleaved BGR u8
580	    const unsigned char* data = (const unsigned char*)resized.data;
581	
582	    ncnn::Mat img(target_w, target_h, 3);  // planar float; channel 0=R, 1=G, 2=B
583	    for (int y = 0; y < target_h; y++) {
584	        const unsigned char* row = data + (size_t)y * target_w * 3;
585	        float* rr = img.channel(0).row(y);
586	        float* gg = img.channel(1).row(y);
587	        float* bb = img.channel(2).row(y);
588	        for (int x = 0; x < target_w; x++) {
589	            const unsigned char* px = row + (size_t)x * 3;  // stored B,G,R
590	            rr[x] = (px[2] / 255.0f - image_mean_[0]) / image_std_[0];
591	            gg[x] = (px[1] / 255.0f - image_mean_[1]) / image_std_[1];
592	            bb[x] = (px[0] / 255.0f - image_mean_[2]) / image_std_[2];
593	        }
594	    }
595	    return img;
596	}
