606	std::shared_ptr<ncnn_llm_gpt_ctx> ncnn_llm_ocr::prefill_hunyuan(const std::string& prompt_text,
607	                                                                const ncnn::Mat& bgr_image) {
608	    int target_h = 0, target_w = 0;
609	    ncnn::Mat image_chw = bgr_to_chw_image_hunyuan(bgr_image, target_h, target_w);
610	    int gh = target_h / patch_size_;
611	    int gw = target_w / patch_size_;
612	    int patch_h = gh / spatial_merge_size_;
613	    int patch_w = gw / spatial_merge_size_;
614	    int num_vision_tokens = patch_h * (patch_w + 1) + 2;
615	
616	    ncnn::Mat vision_features = run_vision_hunyuan(image_chw);
617	    if (vision_features.h != num_vision_tokens) {
618	        printf("[ncnn_llm_ocr] WARNING: vision token count %d != expected %d (grid %dx%d)\n",
619	               vision_features.h, num_vision_tokens, gh, gw);
620	        num_vision_tokens = vision_features.h;
621	    }
622	    printf("[ncnn_llm_ocr] hunyuan vision: resized %dx%d, grid %dx%d, vision_tokens=%d\n",
623	           target_w, target_h, gh, gw, num_vision_tokens);
624	
625	    // Assemble token ids directly (special tokens by id, prompt text via bbpe).
626	    std::vector<int> text_ids = bpe_->encode(prompt_text, false, false);
627	    std::vector<int> token_ids;
628	    token_ids.reserve(3 + num_vision_tokens + text_ids.size() + 1);
629	    token_ids.push_back(bos_id_);
630	    token_ids.push_back(system_end_id_);
631	    token_ids.push_back(image_start_id_);
632	    int first_image_index = (int)token_ids.size();
633	    for (int i = 0; i < num_vision_tokens; i++) token_ids.push_back(image_token_id_);
634	    token_ids.push_back(image_end_id_);
635	    for (int t : text_ids) token_ids.push_back(t);
636	    token_ids.push_back(user_end_id_);
637	
638	    int seq_len = (int)token_ids.size();
639	
640	    // Text embeddings + inject vision features into the image-token slots (in order).
641	    ncnn::Mat token_embed = llm_run_text_embed(*text_embed_net_, token_ids);
642	    for (int i = 0; i < num_vision_tokens; i++) {
643	        float* dst = token_embed.row(first_image_index + i);
644	        const float* src = vision_features.row(i);
645	        memcpy(dst, src, hidden_size_ * sizeof(float));
646	    }
647	
648	    // Build 4-axis position ids (axis0 linear; grid tokens carry (w,h,0)).
649	    std::vector<int> pos_lin(seq_len), pos_w(seq_len), pos_h(seq_len), pos_t(seq_len);
650	    for (int i = 0; i < seq_len; i++) {
651	        pos_lin[i] = i; pos_w[i] = i; pos_h[i] = i; pos_t[i] = i;
652	    }
653	    int start = first_image_index + 1;  // skip the leading "begin" vision token
654	    for (int r = 0; r < patch_h; r++) {
655	        for (int c = 0; c < patch_w + 1; c++) {
656	            int idx = start + r * (patch_w + 1) + c;
657	            if (idx >= seq_len) break;
658	            pos_w[idx] = c;
659	            pos_h[idx] = r;
660	            pos_t[idx] = 0;
661	        }
662	    }
663	
664	    // Prefill decode with KV cache (empty cache in).
665	    const std::vector<int> pos4[4] = { pos_lin, pos_w, pos_h, pos_t };
666	    ncnn::Mat cos_cache, sin_cache;
667	    generate_hunyuan_xdrope_cos_sin(pos4, seq_len, head_dim_, xdrope_section_,
668	                                    rope_theta_, rope_alpha_, cos_cache, sin_cache);
669	
670	    ncnn::Mat mask(seq_len, seq_len);
671	    mask.fill(0.0f);
672	    for (int i = 0; i < seq_len; i++) {
673	        float* row = mask.row(i);
674	        for (int j = i + 1; j < seq_len; j++) row[j] = -1e38f;
675	    }
676	
677	    KVCache kv_cache;
678	    ncnn::Mat decode_out = llm_run_decoder_with_kv(*text_decoder_net_, token_embed, mask,
679	                                                   cos_cache, sin_cache, kv_cache, attn_cnt_, true);
680	    ncnn::Mat last_hidden = decode_out.row_range(seq_len - 1, 1);
681	    ncnn::Mat logits = llm_run_lm_head(*lm_head_net_, last_hidden);
682	    int next_token_id = argmax1d(logits);
683	
684	    auto ctx = std::make_shared<ncnn_llm_gpt_base_ctx>();
685	    ctx->kv_cache = std::move(kv_cache);
686	    ctx->cur_token = next_token_id;
687	    ctx->position_id = seq_len;
688	    return ctx;
689	}
690	
691	std::shared_ptr<ncnn_llm_gpt_ctx> ncnn_llm_ocr::generate_hunyuan(
692	    const std::shared_ptr<ncnn_llm_gpt_ctx>& ctx_in,
693	    const GenerateConfig& cfg,
694	    std::function<void(const std::string&)> callback) {
695	
696	    auto ctx = ctx_in->clone();
697	    std::unordered_set<int> history;
698	    history.insert(ctx->cur_token);
699	
700	    for (int step = 0; step < cfg.max_new_tokens; ++step) {
701	        int tok = ctx->cur_token;
702	        if (eos_ids_.count(tok)) break;
703	
704	        // Emit the current token (skip special / added tokens, e.g. box markers).
705	        bool is_special = (tok >= special_id_begin_) ||
706	                          (additional_special_id_set_.find(tok) != additional_special_id_set_.end());
707	        if (!is_special) {
708	            std::string token_text = bpe_->decode({tok}, true);
709	            if (!token_text.empty()) callback(token_text);
710	        }
711	
712	        // Single-token embedding.
713	        ncnn::Mat cur_embed = llm_run_text_embed(*text_embed_net_, tok);
714	
715	        // Generated text tokens: all 4 xdrope axes = current linear position.
716	        std::vector<int> p1(1, ctx->position_id);
717	        const std::vector<int> pos4[4] = { p1, p1, p1, p1 };
718	        ncnn::Mat cos_cache, sin_cache;
719	        generate_hunyuan_xdrope_cos_sin(pos4, 1, head_dim_, xdrope_section_,
720	                                        rope_theta_, rope_alpha_, cos_cache, sin_cache);
721	        ctx->position_id++;
722	
723	        // Mask [1, kv_len+1] all zeros: the new token attends to all cached positions + itself.
724	        ncnn::Mat mask(1, ctx->kv_cache[0].first.h + 1);
725	        mask.fill(0.0f);
726	
727	        ncnn::Mat decode_out = llm_run_decoder_with_kv(*text_decoder_net_, cur_embed, mask,
728	                                                       cos_cache, sin_cache, ctx->kv_cache, attn_cnt_, false);
729	        ncnn::Mat logits = llm_run_lm_head(*lm_head_net_, decode_out);
730	
731	        LlmTokenSampleConfig sample_cfg;
732	        sample_cfg.vocab_size = vocab_size_;
733	        sample_cfg.temperature = cfg.temperature;
734	        sample_cfg.top_p = cfg.top_p;
735	        sample_cfg.top_k = cfg.top_k;
736	        sample_cfg.repetition_penalty = cfg.repetition_penalty;
737	        sample_cfg.do_sample = cfg.do_sample;
738	        int next_id = llm_select_next_token(logits, history, sample_cfg);
739	
740	        ctx->cur_token = next_id;
741	        history.insert(next_id);
742	    }
743	
744	    return ctx;
745	}
